from fractions import Fraction

def verifier(assign):
    # Validate slots presence
    required = ['b_len','c_len','bd','dc','ce','ea','af','fb']
    for k in required:
        if k not in assign:
            # missing slots
            return (False, None)
    m = assign['b_len']
    n = assign['c_len']
    bd = assign['bd']
    dc = assign['dc']
    ce = assign['ce']
    ea = assign['ea']
    af = assign['af']
    fb = assign['fb']
    # Basic domain checks
    if not all(isinstance(x, int) for x in [m,n,bd,dc,ce,ea,af,fb]):
        return (False, None)
    if m <= 0 or n <= 0 or m == n:
        return (False, None)
    if min(bd,dc,ce,ea,af,fb) <= 0:
        return (False, None)

    # Helper exact rational geometry and Q(sqrt(c)) arithmetic
    def section_point(P, Q, num1, num2):
        w = Fraction(num1 + num2, 1)
        x = (Fraction(num2, 1) * P[0] + Fraction(num1, 1) * Q[0]) / w
        y = (Fraction(num2, 1) * P[1] + Fraction(num1, 1) * Q[1]) / w
        return (x, y)

    def intersect_rational(P0, P1, Q0, Q1):
        v1x = P1[0] - P0[0]
        v1y = P1[1] - P0[1]
        v2x = Q1[0] - Q0[0]
        v2y = Q1[1] - Q0[1]
        dx = Q0[0] - P0[0]
        dy = Q0[1] - P0[1]
        detA = v2x * v1y - v1x * v2y
        if detA == 0:
            return None, None, None
        t = ((-dx) * v2y + v2x * dy) / detA
        u = (v1x * dy - v1y * dx) / detA
        X = (P0[0] + t * v1x, P0[1] + t * v1y)
        return X, t, u

    def param_on_line(Q, E, F):
        ex, ey = E
        fx, fy = F
        qx, qy = Q
        vx = fx - ex
        vy = fy - ey
        if vx != 0:
            tx = (qx - ex) / vx
        else:
            tx = None
        if vy != 0:
            ty = (qy - ey) / vy
        else:
            ty = None
        if tx is not None and ty is not None:
            if tx != ty:
                return None
            return tx
        return tx if tx is not None else ty

    class Qr:
        def __init__(self, p, q, c):
            self.p = Fraction(p, 1) if not isinstance(p, Fraction) else p
            self.q = Fraction(q, 1) if not isinstance(q, Fraction) else q
            self.c = c
        def __add__(self, other):
            assert self.c == other.c
            return Qr(self.p + other.p, self.q + other.q, self.c)
        def __sub__(self, other):
            assert self.c == other.c
            return Qr(self.p - other.p, self.q - other.q, self.c)
        def __mul__(self, other):
            if isinstance(other, Qr):
                assert self.c == other.c
                p = self.p*other.p + self.q*other.q*self.c
                q = self.p*other.q + self.q*other.p
                return Qr(p, q, self.c)
            else:
                return Qr(self.p*other, self.q*other, self.c)
        def __rmul__(self, other):
            return self.__mul__(other)
        def inv(self):
            denom = self.p*self.p - self.q*self.q*self.c
            if denom == 0:
                raise ZeroDivisionError
            return Qr(self.p/denom, -self.q/denom, self.c)
        def __truediv__(self, other):
            if isinstance(other, Qr):
                return self.__mul__(other.inv())
            else:
                return Qr(self.p/other, self.q/other, self.c)
        def approx(self):
            import math
            return float(self.p) + float(self.q)*math.sqrt(self.c)
        def as_pair(self):
            return (self.p, self.q)

    def to_qr_point(P, c):
        return (Qr(P[0], 0, c), Qr(P[1], 0, c))

    def intersect_qr(P0, P1, Q0, Q1, c):
        v1x = P1[0] - P0[0]
        v1y = P1[1] - P0[1]
        v2x = Q1[0] - Q0[0]
        v2y = Q1[1] - Q0[1]
        dx = Q0[0] - P0[0]
        dy = Q0[1] - P0[1]
        detA = v2x * v1y - v1x * v2y
        if detA.p == 0 and detA.q == 0:
            return None, None, None
        t = ((Qr(0,0,c)-dx) * v2y + v2x * dy) / detA
        u = (v1x * dy - v1y * dx) / detA
        Xx = P0[0] + t * v1x
        Xy = P0[1] + t * v1y
        return (Xx, Xy), t, u

    def area_qr(P, Q, R, c):
        ux = Q[0] - P[0]
        uy = Q[1] - P[1]
        vx = R[0] - P[0]
        vy = R[1] - P[1]
        det = ux * vy - uy * vx
        a = Qr(Fraction(1,2), 0, c) * det
        if a.approx() < 0:
            a = Qr(Fraction(-1,2), 0, c) * det
        return a

    def compute_T_for_t(t_val, A, B, C, D, E, F):
        Ex, Ey = E
        Fx, Fy = F
        Q = (Ex + t_val*(Fx-Ex), Ey + t_val*(Fy-Ey))
        P, tPQ, uDE = intersect_rational(C, Q, D, E)
        if P is None:
            return None, None, None, None
        R, tBP, uFD = intersect_rational(B, P, F, D)
        if R is None:
            return None, None, None, None
        Qn, tAR, uEF = intersect_rational(A, R, E, F)
        if Qn is None:
            return None, None, None, None
        T = param_on_line(Qn, E, F)
        return T, uDE, uFD, Qn

    # Build the geometric configuration
    A = (Fraction(0,1), Fraction(0,1))
    B = (Fraction(m,1), Fraction(0,1))
    C = (Fraction(0,1), Fraction(n,1))
    D = section_point(B, C, bd, dc)
    E = section_point(C, A, ce, ea)
    F = section_point(A, B, af, fb)

    # Compute projective map samples
    samp_t = [Fraction(0,1), Fraction(1,1), Fraction(2,3)]
    T_vals = []
    uDE_vals = []
    uFD_vals = []
    for tv in samp_t:
        T, uDE, uFD, Qn = compute_T_for_t(tv, A, B, C, D, E, F)
        if T is None:
            return (False, None)
        T_vals.append(T)
        uDE_vals.append(uDE)
        uFD_vals.append(uFD)

    # Solve t' = (a t + b)/(c t + d), normalize d=1
    def det3(M):
        (a11,a12,a13),(a21,a22,a23),(a31,a32,a33) = M
        return a11*(a22*a33 - a23*a32) - a12*(a21*a33 - a23*a31) + a13*(a21*a32 - a22*a31)
    r0 = (samp_t[0], Fraction(1,1), -T_vals[0]*samp_t[0])
    r1 = (samp_t[1], Fraction(1,1), -T_vals[1]*samp_t[1])
    r2 = (samp_t[2], Fraction(1,1), -T_vals[2]*samp_t[2])
    rhs = (T_vals[0], T_vals[1], T_vals[2])
    M = [r0, r1, r2]
    detM = det3(M)
    if detM == 0:
        return (False, None)
    def replace_col(M, col_idx, col_vec):
        M2 = [list(M[0]), list(M[1]), list(M[2])]
        for i in range(3):
            M2[i][col_idx] = col_vec[i]
        return [tuple(M2[0]), tuple(M2[1]), tuple(M2[2])]
    detA = det3(replace_col(M, 0, rhs))
    detB = det3(replace_col(M, 1, rhs))
    detC = det3(replace_col(M, 2, rhs))
    a_map = detA / detM
    b_map = detB / detM
    c_map = detC / detM
    # Fixed-point quadratic: c t^2 + (1 - a) t - b = 0
    Acoef = c_map
    Bcoef = Fraction(1,1) - a_map
    Ccoef = -b_map
    Disc = Bcoef*Bcoef - 4*Acoef*Ccoef
    if Disc <= 0:
        return (False, None)
    num = Disc.numerator
    den = Disc.denominator
    import math
    def is_square(k):
        if k < 0:
            return False
        s = int(math.isqrt(k))
        return s*s == k
    if not is_square(den):
        return (False, None)
    den_sqrt = int(math.isqrt(den))
    # squarefree part of numerator
    def squarefree_part_and_k(n):
        n_abs = abs(n)
        k = 1
        sf = n_abs
        d = 2
        while d*d <= sf:
            cnt = 0
            while sf % d == 0:
                sf //= d
                cnt += 1
            if cnt >= 2:
                k *= d**(cnt//2)
            if cnt % 2 == 1:
                sf *= d
            d += 1
        return sf, k
    sf, k_factor = squarefree_part_and_k(num)
    if sf <= 1:
        return (False, None)
    factor = Fraction(k_factor, den_sqrt)
    if Acoef == 0:
        return (False, None)
    t0 = (-Bcoef) / (2*Acoef)
    t1 = factor / (2*Acoef)

    # Try both signs and ensure interior conditions
    def build_and_ratio(sign):
        c_int = sf
        # Build EF endpoints in Qr
        E_qr = to_qr_point(E, c_int)
        F_qr = to_qr_point(F, c_int)
        t_qr = Qr(t0, sign*t1, c_int)
        vFE_x = F_qr[0] - E_qr[0]
        vFE_y = F_qr[1] - E_qr[1]
        Q_qr = (E_qr[0] + t_qr * vFE_x, E_qr[1] + t_qr * vFE_y)
        C_qr = to_qr_point(C, c_int)
        D_qr = to_qr_point(D, c_int)
        A_qr = to_qr_point(A, c_int)
        B_qr = to_qr_point(B, c_int)
        P_qr, tCQ, uDE = intersect_qr(C_qr, Q_qr, D_qr, E_qr, c_int)
        if P_qr is None:
            return None
        F_qr = to_qr_point(F, c_int)
        R_qr, tBP, uFD = intersect_qr(B_qr, P_qr, F_qr, D_qr, c_int)
        if R_qr is None:
            return None
        approx_t = Qr(t0, sign*t1, c_int).approx()
        if not (0.0 < approx_t < 1.0):
            return None
        if uDE.approx() <= 0.0 or uDE.approx() >= 1.0:
            return None
        if uFD.approx() <= 0.0 or uFD.approx() >= 1.0:
            return None
        areaPQR = area_qr(P_qr, Q_qr, R_qr, c_int)
        areaABC = Fraction(m*n, 2)
        ratio_qr = Qr(areaABC, Fraction(0,1), c_int) / areaPQR
        return ratio_qr

    ratio1 = build_and_ratio(1)
    ratio2 = build_and_ratio(-1)
    ratio_qr = ratio1 if ratio1 is not None else ratio2
    if ratio_qr is None:
        return (False, None)
    a_coeff, b_coeff = ratio_qr.as_pair()
    # Enforce difficulty: nontrivial radical part and interior points
    if a_coeff.denominator != 1 or b_coeff.denominator != 1:
        return (False, None)
    a_int = int(a_coeff.numerator)
    b_int = int(b_coeff.numerator)
    c_int = int(sf)
    if b_int == 0 or c_int <= 1:
        return (False, None)
    # Provide answer and also store for generator fallback
    assign['a'] = a_int
    assign['b'] = b_int
    assign['c'] = c_int
    answer = a_int*a_int + b_int*b_int + c_int*c_int
    return (True, answer)
